import React from 'react';

const AlphagnitoLogo = ({ size = 36, variant = 'color' }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" fill="none" xmlns="../images/solace_logo.svg">
    <path
      d="M50 5 L88 27.5 L88 72.5 L50 95 L12 72.5 L12 27.5 Z"
      fill={variant === 'white' ? 'rgba(255,255,255,0.15)' : '#1e3a8a'}
    />
    <path
      d="M34 38 L50 28 L50 48 L38 55 Z"
      fill={variant === 'white' ? '#fff' : '#60a5fa'}
      opacity="0.9"
    />
    <path
      d="M50 48 L50 28 L66 38 L62 55 Z"
      fill={variant === 'white' ? 'rgba(255,255,255,0.7)' : '#8b5cf6'}
      opacity="0.9"
    />
    <path
      d="M34 62 L38 55 L50 48 L50 72 Z"
      fill={variant === 'white' ? 'rgba(255,255,255,0.5)' : '#3b82f6'}
      opacity="0.85"
    />
    <path
      d="M66 62 L50 72 L50 48 L62 55 Z"
      fill={variant === 'white' ? 'rgba(255,255,255,0.3)' : '#7c3aed'}
      opacity="0.85"
    />
  </svg>
);

export default AlphagnitoLogo;
